# Check the generated native Windows ICO header and image resolutions. The
# package must not silently fall back to the JDK's default launcher icon.
$iconPath = "app-desktop/build/generated/windows/grbl-commander.ico"
if (-not (Test-Path $iconPath)) {
    throw "Missing generated GRBL Commander Windows icon: $iconPath"
}
$icoBytes = [IO.File]::ReadAllBytes((Resolve-Path $iconPath))
if ($icoBytes.Length -lt 22 -or
    [BitConverter]::ToUInt16($icoBytes, 0) -ne 0 -or
    [BitConverter]::ToUInt16($icoBytes, 2) -ne 1) {
    throw "The generated file is not a valid ICO container."
}
$count = [BitConverter]::ToUInt16($icoBytes, 4)
$dimensions = @()
for ($i = 0; $i -lt $count; $i++) {
    $offset = 6 + 16 * $i
    $width = [int]$icoBytes[$offset]
    if ($width -eq 0) { $width = 256 }
    $dimensions += $width
}
if (16 -notin $dimensions -or 32 -notin $dimensions -or 256 -notin $dimensions) {
    throw "Generated Windows icon must include 16, 32 and 256 pixel variants."
}
Write-Host "Verified multi-resolution Windows app icon: $($dimensions -join ', ')"

# Verify that the generated MSI places the app's shortcut in the Start menu.
# Directory IDs may be generated by WiX, so resolve ancestry in the MSI Directory table.
$ErrorActionPreference = "Stop"
$msiFiles = @(Get-ChildItem "app-desktop/build/compose/binaries/main/msi/*.msi" -File)
if ($msiFiles.Count -ne 1) {
    throw "Expected exactly one MSI installer; found $($msiFiles.Count)."
}

$installer = New-Object -ComObject WindowsInstaller.Installer
$database = $installer.OpenDatabase($msiFiles[0].FullName, 0)

$directories = @{}
$directoryView = $database.OpenView("SELECT Directory, Directory_Parent, DefaultDir FROM Directory")
try {
    $directoryView.Execute()
    while ($record = $directoryView.Fetch()) {
        $directories[$record.StringData(1)] = @{
            Parent = $record.StringData(2)
            Name = $record.StringData(3)
        }
    }
}
finally {
    $directoryView.Close()
}

$shortcutView = $database.OpenView("SELECT Directory_, Name FROM Shortcut")
try {
    $shortcutView.Execute()
    $found = $false
    while ($record = $shortcutView.Fetch()) {
        $directory = $record.StringData(1)
        $shortcut = $record.StringData(2)
        $chain = [System.Collections.Generic.List[string]]::new()
        $seen = [System.Collections.Generic.HashSet[string]]::new()
        $current = $directory
        $startMenuAncestor = $false
        $inAppGroup = $false

        while ($current -and $seen.Add($current)) {
            $chain.Add($current)
            if ($current -match 'ProgramMenu') {
                $startMenuAncestor = $true
            }
            if (-not $directories.ContainsKey($current)) {
                break
            }
            $entry = $directories[$current]
            # MSI DefaultDir may contain a short|long filename representation.
            $longName = ($entry.Name -split '\|')[-1]
            $chain.Add($longName)
            if ($longName -eq "GRBL Commander") {
                $inAppGroup = $true
            }
            $current = $entry.Parent
        }

        Write-Host "MSI shortcut '$shortcut' -> $($chain -join ' / ')"
        if ($startMenuAncestor -and $inAppGroup) {
            $found = $true
        }
    }

    if (-not $found) {
        throw "MSI does not contain a shortcut in the GRBL Commander Start menu group."
    }
    Write-Host "Verified: MSI shortcut is under the GRBL Commander Start menu group."
}
finally {
    $shortcutView.Close()
}

# The native installer must carry the project and third-party legal notices.
$filenames = [System.Collections.Generic.HashSet[string]]::new(
    [System.StringComparer]::OrdinalIgnoreCase
)
$fileView = $database.OpenView("SELECT FileName FROM File")
try {
    $fileView.Execute()
    while ($record = $fileView.Fetch()) {
        $filename = ($record.StringData(1) -split '[|]')[-1]
        [void]$filenames.Add($filename)
    }
}
finally {
    $fileView.Close()
}
foreach ($required in @(
    "THIRD_PARTY_NOTICES.txt",
    "APACHE-2.0.txt",
    "LGPL-3.0.txt",
    "GPL-3.0.txt",
    "OFL-1.1.txt",
    "SKIA.txt",
    "JSERIALCOMM_NOTICE.txt"
)) {
    if (-not $filenames.Contains($required)) {
        throw "MSI is missing required legal resource: $required"
    }
    Write-Host "Verified MSI legal resource: $required"
}
